import { ListItemText } from "@mui/material";
import React from "react";
import { useTranslation } from "react-i18next";

const ActStartPopupContent = () => {
  const { t, i18n } = useTranslation();
  return (
    <>
      <ListItemText sx={{ display: "list-item" }}>
        {t("what_going_to_learn_1")}
      </ListItemText>
      <ListItemText sx={{ display: "list-item" }}>
        {t("what_going_to_learn_2")}
        <br></br>

        {t("what_going_to_learn_3_1")}
        <br></br>
        {t("what_going_to_learn_3_2")}
      </ListItemText>
      <ListItemText sx={{ display: "list-item" }}>
        {t("what_going_to_learn_4")}
      </ListItemText>
      <ListItemText sx={{ display: "list-item" }}>
        {t("what_going_to_learn_5")}
      </ListItemText>
    </>
  );
};

export default ActStartPopupContent;
