        tempclrnm[locofword] = 2;
        setClrnm(tempclrnm);

        showfeedback = 2;
        setShowfeedback(showfeedback);
        console.log("showfeedback ", showfeedback);

        var text =
          '<div><span style="color:red;">' +
          `${selectedword}` +
          "</span>" +
          " is " +
          `${selectedword_type}` +
          ", not conjunction.";
